    private static void await(CountDownLatch gate)throws Exception{check(gate.await(10,TimeUnit.SECONDS),"worker gate reached");}
    private static void uninterruptible(CountDownLatch gate){boolean done=false;while(!done)try{done=gate.await(10,TimeUnit.SECONDS);check(done,"worker gate released");}catch(InterruptedException ignored){}}
